package com.coworkhub.controller;
import com.coworkhub.entity.*;import com.coworkhub.repository.*;import org.springframework.web.bind.annotation.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.transaction.annotation.Transactional;import java.util.*;
@RestController @RequestMapping("/api/miembros")public class MemberController{
 private final MemberRepository members;private final MembershipPlanRepository plans;private final UserAccountRepository users;private final PasswordEncoder encoder;private final BookingRepository bookings;private final java.time.Clock clock;
 public MemberController(MemberRepository m,MembershipPlanRepository p,UserAccountRepository u,PasswordEncoder e,BookingRepository b,java.time.Clock c){members=m;plans=p;users=u;encoder=e;bookings=b;clock=c;}
 record MemberCreate(@jakarta.validation.constraints.NotBlank String documentNumber,@jakarta.validation.constraints.NotBlank String fullName,@jakarta.validation.constraints.Email @jakarta.validation.constraints.NotBlank String email,@jakarta.validation.constraints.NotNull Long planId,@jakarta.validation.constraints.NotBlank String username,@jakarta.validation.constraints.Size(min=6) String password){} record MemberUpdate(@jakarta.validation.constraints.NotBlank String fullName,@jakarta.validation.constraints.Email @jakarta.validation.constraints.NotBlank String email,@jakarta.validation.constraints.NotNull Long planId){}
 @GetMapping @PreAuthorize("hasAnyRole('ADMIN','RECEPTIONIST')")public List<Member> all(@RequestParam(required=false) String nombre,@RequestParam(required=false) Enums.MemberStatus estado){return members.findAll().stream().filter(m->nombre==null||nombre.isBlank()||m.fullName.toLowerCase().contains(nombre.toLowerCase())).filter(m->estado==null||m.status==estado).toList();}
 @GetMapping("/{id}")@PreAuthorize("hasAnyRole('ADMIN','RECEPTIONIST') or (hasRole('MEMBER') and @memberAccess.isOwner(authentication,#id))")public Member get(@PathVariable Long id){return members.findById(id).orElseThrow();}
 @PostMapping @PreAuthorize("hasAnyRole('ADMIN','RECEPTIONIST')")@Transactional public Member create(@jakarta.validation.Valid @RequestBody MemberCreate d){if(d.documentNumber()==null||d.fullName()==null||d.email()==null||d.username()==null||d.password()==null||d.planId()==null)throw new IllegalArgumentException("Todos los campos son obligatorios");if(members.existsByDocumentNumber(d.documentNumber())||members.existsByEmail(d.email())||users.findByUsername(d.username()).isPresent())throw new IllegalStateException("Documento, email o usuario duplicado (RN-11)");Member m=new Member();m.documentNumber=d.documentNumber();m.fullName=d.fullName();m.email=d.email();m.plan=plans.findById(d.planId()).orElseThrow();m=members.save(m);UserAccount u=new UserAccount();u.username=d.username();u.password=encoder.encode(d.password());u.role=Enums.Role.MEMBER;u.member=m;users.save(u);return m;}
 @PutMapping("/{id}")@PreAuthorize("hasAnyRole('ADMIN','RECEPTIONIST')")public Member update(@PathVariable Long id,@jakarta.validation.Valid @RequestBody MemberUpdate d){Member m=members.findById(id).orElseThrow();m.fullName=d.fullName();m.email=d.email();m.plan=plans.findById(d.planId()).orElseThrow();return members.save(m);}
 @PatchMapping("/{id}/suspender")@PreAuthorize("hasAnyRole('ADMIN','RECEPTIONIST')")public Member suspend(@PathVariable Long id){Member m=members.findById(id).orElseThrow();m.status=Enums.MemberStatus.SUSPENDED;return members.save(m);}
 @PatchMapping("/{id}/activar")@PreAuthorize("hasAnyRole('ADMIN','RECEPTIONIST')")public Member activate(@PathVariable Long id){Member m=members.findById(id).orElseThrow();m.status=Enums.MemberStatus.ACTIVE;return members.save(m);}
 @DeleteMapping("/{id}")@PreAuthorize("hasAnyRole('ADMIN','RECEPTIONIST')")@Transactional public Map<String,String> delete(@PathVariable Long id){Member m=members.findById(id).orElseThrow();if(!bookings.findByMemberId(id).isEmpty())throw new IllegalStateException("No se puede eliminar un miembro que tenga reservas (RN-12)");if(m.account!=null)users.delete(m.account);members.delete(m);return Map.of("mensaje","Miembro eliminado");}
 @GetMapping("/{id}/consumo")@PreAuthorize("hasAnyRole('ADMIN','RECEPTIONIST') or (hasRole('MEMBER') and @memberAccess.isOwner(authentication,#id))")public Map<String,Object> consumption(@PathVariable Long id,@RequestParam(required=false) String mes){Member m=members.findById(id).orElseThrow();java.time.YearMonth month=mes==null?java.time.YearMonth.now(clock):java.time.YearMonth.parse(mes);var monthBookings=bookings.findByMemberIdAndStartTimeBetween(id,month.atDay(1).atStartOfDay(),month.plusMonths(1).atDay(1).atStartOfDay()).stream().filter(b->b.status==Enums.BookingStatus.CONFIRMED||b.status==Enums.BookingStatus.COMPLETED).toList();double used=monthBookings.stream().mapToDouble(b->java.time.Duration.between(b.startTime,b.endTime).toMinutes()/60.0).sum();double included=m.plan.includedHoursPerMonth;return Map.of("miembroId",id,"mes",month.toString(),"horasIncluidas",included,"horasUsadas",used,"horasRestantes",Math.max(0,included-used),"horasExcedentes",Math.max(0,used-included));}
}
